import XCTest

final class StandupTests: XCTestCase {
    let dumpDir = "/tmp/uitest_dumps"

    func dump(_ app: XCUIApplication, _ name: String) {
        try? FileManager.default.createDirectory(atPath: dumpDir, withIntermediateDirectories: true)
        try? app.debugDescription.write(toFile: "\(dumpDir)/\(name).txt", atomically: true, encoding: .utf8)
    }

    func log(_ s: String) {
        try? FileManager.default.createDirectory(atPath: dumpDir, withIntermediateDirectories: true)
        let path = "\(dumpDir)/steps.log"
        let line = "\(Date()) \(s)\n"
        if let data = FileManager.default.contents(atPath: path) {
            try? (data + line.data(using: .utf8)!).write(to: URL(fileURLWithPath: path))
        } else {
            try? line.write(toFile: path, atomically: true, encoding: .utf8)
        }
    }

    func dismissModalIfNeeded(_ app: XCUIApplication) {
        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 3) {
            gotIt.tap()
            log("dismissed threads modal")
            Thread.sleep(forTimeInterval: 1)
        }
    }

    func testFlow() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        log("activated")

        dismissModalIfNeeded(app)

        if !app.navigationBars["Team Standup"].waitForExistence(timeout: 5) {
            let standup = app.staticTexts["Team Standup"].firstMatch
            XCTAssertTrue(standup.waitForExistence(timeout: 30), "home not visible")
            standup.tap()
            log("tapped Team Standup on home")
            XCTAssertTrue(app.navigationBars["Team Standup"].waitForExistence(timeout: 15))
        }
        log("in room")
        dismissModalIfNeeded(app)

        let headerTitle = app.buttons["Team Standup"].firstMatch
        XCTAssertTrue(headerTitle.waitForExistence(timeout: 10), "room header title button not found")
        headerTitle.tap()
        log("tapped room header title")
        Thread.sleep(forTimeInterval: 3)
        dismissModalIfNeeded(app)
        dump(app, "5_roomdetails")

        let members = app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH[cd] 'member'")).firstMatch
        if members.waitForExistence(timeout: 10) {
            members.tap()
            log("tapped members row")
        } else {
            let people = app.staticTexts["People"].firstMatch
            if people.waitForExistence(timeout: 5) {
                people.tap()
                log("tapped people row")
            } else {
                log("no members row found")
            }
        }
        Thread.sleep(forTimeInterval: 3)
        dump(app, "6_memberslist")

        let bob = app.staticTexts["Bob"].firstMatch
        if bob.waitForExistence(timeout: 10) {
            bob.tap()
            log("tapped Bob")
        } else {
            log("Bob not found in members list")
        }
        Thread.sleep(forTimeInterval: 3)
        dump(app, "7_profile")
        log("done")
    }
}

